//! Where the Australian reference reading of a sentence comes from.
//!
//! Every source implements [`ReferenceSource`], so the Practice screen does not care
//! whether a sentence was narrated by a person, spoken by a macOS voice, or
//! (from M5) generated by the voice-cloning sidecar.

pub mod cloned;
pub mod narration;
pub mod system_voice;
pub mod text;

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SourceKind {
    /// A person's recording, split into sentences.
    Narration,
    /// Built-in macOS speech synthesis (synthetic; fallback only).
    SystemVoice,
    /// Neural voice-cloning sidecar (Chatterbox).
    Cloned,
}

#[derive(Debug, Clone, PartialEq)]
pub struct RenderedAudio {
    /// 16 kHz mono.
    pub samples: Vec<f32>,
    /// `(word, start_s, end_s)` when the source knows them; M2 alignment fills these otherwise.
    pub word_timings: Option<Vec<(String, f32, f32)>>,
}

#[derive(Debug, thiserror::Error)]
pub enum ReferenceError {
    #[error("the narration has no audio for sentence {0}")]
    NoAudioForSentence(usize),
    #[error("system voice unavailable: {0}")]
    SystemVoice(String),
    #[error("neural voice: {0}")]
    Cloned(String),
    #[error(transparent)]
    Audio(#[from] audio_io::AudioError),
    #[error("{0}")]
    Analysis(#[from] analysis::AnalysisError),
}

pub type Result<T> = std::result::Result<T, ReferenceError>;

pub trait ReferenceSource: Send {
    fn id(&self) -> &str;
    fn kind(&self) -> SourceKind;
    /// Reference audio for sentence `index` whose text is `text`.
    fn render(&mut self, index: usize, text: &str) -> Result<RenderedAudio>;
}
